// These methods run on WLED's 8 KiB loop task. Nested read/hash/encoding calls
// must not put kilobyte scratch arrays on its stack. Prefer PSRAM when present,
// and return an error if the checked allocation cannot be satisfied.
struct ScratchDeleter {
  void operator()(uint8_t* bytes) const { p_free(bytes); }
};
using ScratchBuffer = std::unique_ptr<uint8_t, ScratchDeleter>;
ScratchBuffer scratchBuffer(size_t size) {
  return ScratchBuffer(static_cast<uint8_t*>(p_malloc(std::max<size_t>(1, size))));
}

String digestHex(const uint8_t* bytes) {
  char text[65];
  constexpr char digits[] = "0123456789abcdef";
  for (size_t i = 0; i < 32; ++i) { text[2*i] = digits[bytes[i] >> 4]; text[2*i+1] = digits[bytes[i] & 15]; }
  text[64] = 0;
  return String(text);
}

bool fileDigest(File& file, String& digest) {
  if (!file || !file.seek(0)) return false;
  auto buffer = scratchBuffer(MAX_TRANSFER_CHUNK);
  if (!buffer) return false;
  mbedtls_sha256_context context;
  mbedtls_sha256_init(&context);
  bool valid = mbedtls_sha256_starts(&context, 0) == 0;
  uint8_t result[32];
  size_t remaining = file.size();
  while (valid && remaining) {
    size_t count = file.read(buffer.get(), std::min(remaining, MAX_TRANSFER_CHUNK));
    valid = count > 0 && mbedtls_sha256_update(&context, buffer.get(), count) == 0;
    remaining -= count;
    yield();
  }
  valid = valid && mbedtls_sha256_finish(&context, result) == 0;
  mbedtls_sha256_free(&context);
  if (valid) digest = digestHex(result);
  return valid;
}

String textDigest(const String& body) {
  uint8_t digest[32];
  if (mbedtls_sha256(reinterpret_cast<const uint8_t*>(body.c_str()), body.length(), digest, 0)) return String();
  return digestHex(digest);
}

bool encodeBytes(const uint8_t* bytes, size_t size, String& encoded) {
  if (size > MAX_TRANSFER_CHUNK) return false;
  const size_t capacity = 4 * ((size + 2) / 3) + 1;
  auto buffer = scratchBuffer(capacity);
  if (!buffer) return false;
  size_t count = 0;
  if (mbedtls_base64_encode(buffer.get(), capacity, &count, bytes, size)) return false;
  encoded = "";
  return encoded.concat(reinterpret_cast<const char*>(buffer.get()), count) && encoded.length() == count;
}

// Reject whitespace, embedded padding, and oversize data before decoding.
bool decodeBytes(const char* text, uint8_t* output, size_t capacity, size_t& written) {
  return decodeBase64(text, output, capacity, written);
}

bool publicFile(const String& path) {
  return path == F("/presets.json") || (path.startsWith(F("/palette")) && path.endsWith(F(".json")));
}

bool stagedRoute(const String& path) {
  return path == F("/json") || path == F("/json/state") || path == F("/json/si") || path == F("/json/cfg")
    || path == F("/settings/wifi") || path == F("/settings/leds") || path == F("/settings/ui")
    || path == F("/settings/sync") || path == F("/settings/time") || path == F("/settings/sec")
    || path == F("/settings/dmx") || path == F("/settings/um") || path == F("/settings/2D");
}

// Reserved WLED files must have the expected root shape. Configuration restores
// additionally require the revision, identity, and LED hardware backup fields.
bool validReservedFile(const String& path) {
  if (path != F("/cfg.json") && path != F("/presets.json")) return true;
  File file = WLED_FS.open(TRANSFER_FILE, "r");
  if (!file) return false;
  int first;
  do { first = file.read(); } while (first == ' ' || first == '\n' || first == '\r' || first == '\t');
  if (first != '{') return false;
  if (path == F("/presets.json")) return true;
  file.seek(0);
  DynamicJsonDocument filter(256);
  filter["rev"] = true;
  filter["id"]["name"] = true;
  filter["hw"]["led"]["total"] = true;
  DynamicJsonDocument document(768);
  if (filter.overflowed()) return false;
  if (deserializeJson(document, file, DeserializationOption::Filter(filter))) return false;
  JsonArray revision = document["rev"].as<JsonArray>();
  return revision.size() == 2 && revision[0].is<unsigned>() && revision[1].is<unsigned>()
    && document["id"]["name"].is<const char*>() && document["hw"]["led"]["total"].is<unsigned>();
}
